import React, { useState } from "react";
import { Hotel } from "../type/Hotel";


import "./AddHotel.css";

const AddHotelScreen: React.FC = () => {
  const [hotel, setHotel] = useState<Hotel>({
    hotelId: 0,
    hotelName: "",
    hotelAddress: "",
  });

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setHotel({ ...hotel, [name]: name === "hotelId" ? parseInt(value) : value });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    // try {
    //   await saveHotel(hotel);
    //   alert("Hotel saved successfully");
    //   setHotel({ hotelId: 0, hotelName: "", hotelAddress: "" });
    // } catch (error: any) {
    //   alert("Error saving hotel: " + (error.response?.data?.message || error.message));
    // }
  };

  return (
    <div className="add-hotel-container">
      <h2>Add Hotel</h2>
      <form onSubmit={handleSubmit}>
        <label>Hotel ID</label>
        <input
          type="number"
          name="hotelId"
          value={hotel.hotelId}
          onChange={handleChange}
          required
        />

        <label>Hotel Name</label>
        <input
          type="text"
          name="hotelName"
          value={hotel.hotelName}
          onChange={handleChange}
          required
        />

        <label>Hotel Address</label>
        <input
          type="text"
          name="hotelAddress"
          value={hotel.hotelAddress}
          onChange={handleChange}
          required
        />

        <button type="submit">Save</button>
      </form>
    </div>
  );
};

export default AddHotelScreen;
